import openpyxl
from datetime import datetime, timedelta

# Load the workbook
wb = openpyxl.load_workbook('input.xlsx')
ws = wb.active

# The source data is in E1:F6 (PastedSourceDate, PastedSourceValue)
# We need to read the source data into a dictionary for quick lookup
# Key: date, Value: corresponding value
source_data = {}
for row in range(2, 7):  # Rows 2 to 6 contain data
    date_cell = ws.cell(row=row, column=5)  # Column E
    value_cell = ws.cell(row=row, column=6)  # Column F

    # Check if the date cell has a valid date
    if date_cell.value is not None:
        # Handle both datetime objects and string dates
        if isinstance(date_cell.value, datetime):
            date_key = date_cell.value
        else:
            # Try to parse if it's a string
            try:
                date_key = datetime.strptime(str(date_cell.value), '%Y-%m-%d %H:%M:%S')
            except:
                try:
                    date_key = datetime.strptime(str(date_cell.value), '%Y-%m-%d')
                except:
                    continue

        source_data[date_key] = value_cell.value

# The timeline is in Column A, rows 2 to 11 (A2:A11)
# We need to align the source data against this timeline in B2:C11
# B column: aligned dates (from timeline)
# C column: aligned values (from source data)

for row in range(2, 12):  # Rows 2 to 11
    timeline_date_cell = ws.cell(row=row, column=1)  # Column A

    # Get the timeline date
    if timeline_date_cell.value is not None:
        if isinstance(timeline_date_cell.value, datetime):
            timeline_date = timeline_date_cell.value
        else:
            try:
                timeline_date = datetime.strptime(str(timeline_date_cell.value), '%Y-%m-%d %H:%M:%S')
            except:
                try:
                    timeline_date = datetime.strptime(str(timeline_date_cell.value), '%Y-%m-%d')
                except:
                    timeline_date = None

        # Write the timeline date to column B
        ws.cell(row=row, column=2).value = timeline_date

        # Look up the value from source data
        if timeline_date in source_data:
            ws.cell(row=row, column=3).value = source_data[timeline_date]
        else:
            ws.cell(row=row, column=3).value = None  # No matching value
    else:
        ws.cell(row=row, column=2).value = None
        ws.cell(row=row, column=3).value = None

# Save the workbook
wb.save('output.xlsx')
